const clientes = $input.all();

const hoy = new Date();

const inicioHoy = Date.UTC(
  hoy.getFullYear(),
  hoy.getMonth(),
  hoy.getDate()
);

const proximos = [];

for (const item of clientes) {

  const fecha = item.json.fecha_importante;

  // Ignorar fechas vacías o inválidas
  if (
    typeof fecha !== "string" ||
    !/^\d{4}-\d{2}-\d{2}$/.test(fecha)
  ) {
    continue;
  }

  const [anio, mes, dia] = fecha.split("-").map(Number);

  const fechaUTC = Date.UTC(anio, mes - 1, dia);

  const diasRestantes = Math.round(
    (fechaUTC - inicioHoy) / 86400000
  );

  // Seleccionar fechas entre hoy y los próximos 7 días
  if (diasRestantes >= 0 && diasRestantes <= 7) {

    proximos.push({
      json: {
        ...item.json,
        dias_restantes: diasRestantes
      }
    });

  }
}

return proximos;

const clientes = $input.all();

return clientes.map(item => {
  const c = item.json;

  return {
    json: {
      ...c,
      recordatorio: `Hola Paulina. Recuerda que ${c.nombre} tiene un ${c.tipo_fecha.toLowerCase()} el ${c.fecha_importante}. Faltan ${c.dias_restantes} días. Puedes contactarlo para ofrecer un arreglo floral.`
    }
  };
});
